(()=>{'use strict';const D={"report-2026-11-28-morning-briefing": {"ko": {"title": "11월 28일 아침 브리핑: 반등한 시장, 남아 있는 생활의 비용", "summary": "한국과 미국 증시가 반등했지만 가계의 가처분소득까지 함께 늘어난 것은 아니다. 정치권은 개혁과제의 집행, 당내 징계, 대법원장 탄핵 일정을 놓고 갈등을 이어간다. 토요일 아침에는 전날의 종가와 오늘의 일정, 결정과 주장을 분리해 읽는다.", "href": "2026-11-28-morning-briefing-ko.html"}, "en": {"title": "28 November morning briefing: markets rebound, household costs remain", "summary": "Korean and US shares rebounded, but household disposable income did not rise with them. Politics remains focused on reform implementation, party discipline and a proposed impeachment timetable. On Saturday morning, distinguish yesterday's closes from today's plans, and decisions from demands.", "href": "2026-11-28-morning-briefing-en.html"}, "ja": {"title": "11月28日朝のブリーフィング：反発する市場、残る家計の負担", "summary": "韓国と米国の株式市場は反発したが、家計の可処分所得が同じように増えたわけではない。政治では改革の実行、党内処分、最高裁長官の弾劾日程をめぐる対立が続く。土曜の朝は、前日の終値と今日の予定、決定と主張を分けて読む。", "href": "2026-11-28-morning-briefing-ja.html"}, "zh": {"title": "11月28日晨间简报：市场反弹，家庭开支压力仍在", "summary": "韩国和美国股市反弹，但家庭可支配收入并没有同步增长。政治焦点仍是改革落实、党内处分和最高法院院长弹劾时间表。周六早晨，须把昨日收盘和今天安排、已作决定和政治诉求分开阅读。", "href": "2026-11-28-morning-briefing-zh.html"}, "es": {"title": "Resumen del 28 de noviembre: rebotan los mercados, persisten los costes familiares", "summary": "Las bolsas coreanas y estadounidenses rebotaron, pero la renta disponible de los hogares no aumentó con ellas. La política sigue centrada en aplicar reformas, las sanciones internas y el calendario propuesto para una destitución judicial. Este sábado conviene separar los cierres de ayer de los planes de hoy, y las decisiones de las exigencias.", "href": "2026-11-28-morning-briefing-es.html"}}, "report-2026-11-28-income-between-growth": {"ko": {"title": "성장률은 뛰는데, 쓸 수 있는 돈은 줄었다", "summary": "경제가 좋아졌다는 뉴스와 생활이 팍팍하다는 말은 동시에 참일 수 있다. 국가데이터처의 2026년 3분기 가계동향조사에서 가구당 월평균 소득은 548만원으로 1년 전보다 0.8% 늘었다. 그러나 처분가능소득은 430만6000원으로 1.7% 줄었다. 첫 숫자만 보면 회복이고, 두 번째 숫자까지 보면 부담이다.", "href": "2026-11-28-income-between-growth-ko.html"}, "en": {"title": "Growth is rising, but the money left to spend fell", "summary": "A stronger economy and tighter household budgets can coexist. In Korea's third-quarter 2026 Household Income and Expenditure Survey, average monthly household income rose 0.8% from a year earlier to 5.48 million won. Disposable income, however, fell 1.7% to 4.306 million won. The first figure suggests recovery. The second reveals a squeeze.", "href": "2026-11-28-income-between-growth-en.html"}, "ja": {"title": "成長率は上がっても、使えるお金は減った", "summary": "経済が良くなったというニュースと、暮らしが厳しいという実感は両立する。韓国の2026年7～9月期家計動向調査では、1世帯当たり月平均所得は548万ウォンで前年同期比0.8%増えた。一方、可処分所得は430万6000ウォンで1.7%減った。最初の数字だけなら回復だが、二つ目まで見れば負担が浮かぶ。", "href": "2026-11-28-income-between-growth-ja.html"}, "zh": {"title": "经济增长加快，可用于消费的钱却减少了", "summary": "经济向好与生活拮据可能同时发生。韩国2026年第三季度家庭收支调查显示，家庭月均收入为548万韩元，同比增加0.8%。但可支配收入为430.6万韩元，减少1.7%。只看前一个数字像是复苏，加上后一个数字便能看出压力。", "href": "2026-11-28-income-between-growth-zh.html"}, "es": {"title": "La economía crece, pero queda menos dinero para gastar", "summary": "Una economía más fuerte y unos presupuestos familiares ajustados pueden coexistir. En la encuesta coreana del tercer trimestre de 2026, los ingresos mensuales medios por hogar aumentaron un 0,8% interanual, hasta 5,48 millones de wones. Sin embargo, los ingresos disponibles cayeron un 1,7%, hasta 4,306 millones. La primera cifra sugiere recuperación; la segunda revela presión.", "href": "2026-11-28-income-between-growth-es.html"}}, "report-2026-11-28-robot-data-before-motion": {"ko": {"title": "로봇의 다음 병목은 팔이 아니라 기록이다", "summary": "같은 동작을 배워도 기록하는 방식이 다르면 로봇의 경험을 나누기 어렵다. 산업통상부 국가기술표준원은 11월 27일 로봇 조작 학습을 위한 데이터셋 KS 제정안을 예고하고 60일간 의견을 받는다고 밝혔다. 로봇이 무엇을 할지에 앞서, 무엇을 어떻게 배웠는지 남기는 규칙을 맞추려는 시도다.", "href": "2026-11-28-robot-data-before-motion-ko.html"}, "en": {"title": "The next robot bottleneck is the record, not the arm", "summary": "Robots cannot easily share experience if the same movement is recorded in incompatible ways. On November 27, the Korean Agency for Technology and Standards announced a proposed KS standard for robot-manipulation learning datasets, with a 60-day comment period. Before asking what a robot can do, the proposal asks how to record what it learned.", "href": "2026-11-28-robot-data-before-motion-en.html"}, "ja": {"title": "ロボットの次のボトルネックは、腕ではなく記録だ", "summary": "同じ動作でも記録方法が違えば、ロボットの経験は共有しにくい。韓国の国家技術標準院は11月27日、ロボット操作学習用データセットのKS制定案を公示し、60日間意見を募ると発表した。何ができるかの前に、何をどう学んだかを記録するルールをそろえる試みだ。", "href": "2026-11-28-robot-data-before-motion-ja.html"}, "zh": {"title": "机器人的下一个瓶颈，不在机械臂而在记录", "summary": "即使学习同一种动作，记录方式不同，机器人的经验也很难共享。韩国国家技术标准院11月27日宣布，就机器人操作学习数据集KS标准草案征求意见，期限为60天。在讨论机器人能做什么之前，先统一如何记录它学过什么。", "href": "2026-11-28-robot-data-before-motion-zh.html"}, "es": {"title": "El próximo cuello de botella del robot es el registro, no el brazo", "summary": "Los robots difícilmente comparten experiencia si un mismo movimiento se registra de formas incompatibles. El 27 de noviembre, la Agencia Coreana de Tecnología y Normas anunció una propuesta KS sobre conjuntos de datos para aprender manipulación robótica, con 60 días de consulta. Antes de preguntar qué puede hacer un robot, se plantea cómo registrar lo que aprendió.", "href": "2026-11-28-robot-data-before-motion-es.html"}}, "report-2026-11-28-internal-sales-denominator": {"ko": {"title": "재벌 내부거래 35%, 분모를 빼면 기사가 바뀐다", "summary": "계열사끼리 거래한 돈이 841조원이라는 숫자와 277조원이라는 숫자가 같은 자료에 있다. 어느 쪽이 틀린 것이 아니다. 공정거래위원회의 2026년 공시대상기업집단 분석은 2025년 거래를 대상으로 국내 계열사 간 거래와 국외 계열사와의 거래를 나누었다. 숫자의 크기를 논하기 전에 거래의 경계를 그어야 한다.", "href": "2026-11-28-internal-sales-denominator-ko.html"}, "en": {"title": "Intragroup sales are 35%. Leave out the denominator and the story changes", "summary": "The same report contains both 841 trillion won and 277 trillion won in affiliate transactions. Neither is necessarily wrong. The Fair Trade Commission's 2026 analysis of business groups subject to disclosure examines 2025 transactions and separates dealings among domestic affiliates from dealings with overseas affiliates. Before debating scale, draw the boundary.", "href": "2026-11-28-internal-sales-denominator-en.html"}, "ja": {"title": "内部取引35%、分母を抜けば記事が変わる", "summary": "同じ資料に系列企業間取引841兆ウォンと277兆ウォンという数字がある。どちらかが誤りなのではない。韓国公正取引委員会の2026年企業集団分析は2025年の取引を対象に、国内系列間と国外系列との取引を区分した。規模を論じる前に、取引の境界を引く必要がある。", "href": "2026-11-28-internal-sales-denominator-ja.html"}, "zh": {"title": "内部交易占35%，省略分母就会改写报道", "summary": "同一份资料中，关联企业交易额既有841万亿韩元，也有277万亿韩元。两者并不矛盾。韩国公平交易委员会2026年企业集团分析以2025年交易为对象，区分境内关联企业之间的交易和与境外关联企业的交易。讨论规模之前，先划清范围。", "href": "2026-11-28-internal-sales-denominator-zh.html"}, "es": {"title": "Las ventas intragrupo son el 35%: sin el denominador cambia la noticia", "summary": "El mismo informe contiene 841 billones de wones y 277 billones en operaciones entre empresas vinculadas. No es una contradicción. El análisis de 2026 de la Comisión de Comercio Justo de Corea examina operaciones de 2025 y separa las realizadas entre filiales nacionales de las efectuadas con filiales extranjeras. Antes de discutir el tamaño, hay que trazar el límite.", "href": "2026-11-28-internal-sales-denominator-es.html"}}, "report-2026-11-28-consumption-buffer": {"ko": {"title": "더 썼는데 더 잘산 것은 아니다", "summary": "소비가 늘었다는 발표가 소비자의 여유를 뜻하지 않을 때가 있다. 2026년 3분기 가계동향조사에서 월평균 소비지출은 303만원으로 2.9% 늘었지만 흑자액은 127만6000원으로 11.2% 감소했다. 장바구니가 무거워진 만큼 가계의 완충재가 얇아졌을 수 있다는 뜻이다.", "href": "2026-11-28-consumption-buffer-ko.html"}, "en": {"title": "Spending more is not the same as living better", "summary": "Rising consumption does not always mean consumers have more room to breathe. In Korea's third-quarter 2026 household survey, average monthly consumption expenditure rose 2.9% to 3.03 million won, while the surplus fell 11.2% to 1.276 million won. A heavier shopping basket may come with a thinner financial cushion.", "href": "2026-11-28-consumption-buffer-en.html"}, "ja": {"title": "多く使っても、暮らしが豊かになったとは限らない", "summary": "消費増の発表が、消費者の余裕を意味しない場合がある。韓国の2026年7～9月期家計調査で月平均消費支出は303万ウォン、2.9%増だったが、黒字額は127万6000ウォンで11.2%減った。買い物かごが重くなる一方で、家計の緩衝材は薄くなった可能性がある。", "href": "2026-11-28-consumption-buffer-ja.html"}, "zh": {"title": "花得更多，不代表过得更好", "summary": "消费增加，有时并不意味着消费者更宽裕。韩国2026年第三季度家庭调查中，月均消费支出为303万韩元，增加2.9%；结余为127.6万韩元，减少11.2%。购物篮更重的同时，家庭的缓冲垫可能变薄。", "href": "2026-11-28-consumption-buffer-zh.html"}, "es": {"title": "Gastar más no significa vivir mejor", "summary": "El aumento del consumo no siempre significa mayor holgura. En la encuesta coreana del tercer trimestre de 2026, el gasto mensual medio de consumo subió un 2,9%, a 3,03 millones de wones, mientras que el excedente cayó un 11,2%, a 1,276 millones. Una cesta más pesada puede acompañarse de un colchón financiero más fino.", "href": "2026-11-28-consumption-buffer-es.html"}}, "report-2026-11-28-museum-two-records": {"ko": {"title": "같은 백제, 다른 두 권의 기록", "summary": "한성백제박물관에서 두 역사서의 시선을 비교할 수 있는 전시가 시작됐다. 서울시는 11월 27일부터 2027년 2월 21일까지 기획전시실 1·2에서 ‘삼국사기·삼국유사, 백제를 기록하다’를 연다고 안내했다. 오래된 책을 한자리에 놓는 일은 보존의 성과이자 기록의 차이를 읽는 출발점이다.", "href": "2026-11-28-museum-two-records-ko.html"}, "en": {"title": "The same Baekje, two different records", "summary": "A new exhibition at the Seoul Baekje Museum compares the perspectives of two historical works. Seoul says 'Samguk Sagi and Samguk Yusa: Recording Baekje' runs in Special Exhibition Rooms 1 and 2 from November 27 to February 21, 2027. Bringing old books together is both an achievement of preservation and a starting point for reading their differences.", "href": "2026-11-28-museum-two-records-en.html"}, "ja": {"title": "同じ百済、異なる二つの記録", "summary": "ソウルの漢城百済博物館で、二つの歴史書の視点を比べる展覧会が始まった。ソウル市は11月27日から2027年2月21日まで企画展示室1・2で『三国史記・三国遺事、百済を記録する』を開くと案内する。古書を集めることは保存の成果であると同時に、記録の違いを読む出発点だ。", "href": "2026-11-28-museum-two-records-ja.html"}, "zh": {"title": "同一个百济，两种不同的记录", "summary": "首尔汉城百济博物馆的新展览比较两部史书的视角。首尔市介绍，《三国史记·三国遗事，记录百济》于11月27日至2027年2月21日在特别展厅1、2举行。让古籍聚在一起，既是保存成果，也是阅读记录差异的起点。", "href": "2026-11-28-museum-two-records-zh.html"}, "es": {"title": "El mismo Baekje, dos registros diferentes", "summary": "Una nueva exposición del Museo Baekje de Seúl compara las perspectivas de dos obras históricas. Según la ciudad, 'Samguk Sagi y Samguk Yusa: registrar Baekje' abre del 27 de noviembre al 21 de febrero de 2027 en las salas temporales 1 y 2. Reunir libros antiguos es un logro de conservación y un punto de partida para leer sus diferencias.", "href": "2026-11-28-museum-two-records-es.html"}}, "report-2026-11-28-book-algorithm-disobedience": {"ko": {"title": "스크롤을 멈춘 뒤, 무엇을 되찾을까", "summary": "기술을 버릴지 말지가 아니라 기술이 누구의 목표에 맞춰 작동하는지를 묻는 책이 나왔다. 주한나의 ‘알고리즘 불복종’이다. 11월 27일 뉴스공장 백년위원회 인터뷰와 공개 서지·목차를 함께 보면 이 책의 질문은 편리함의 찬반보다 일상의 선택권에 가깝다. 이 글은 책 전체를 읽은 완독 서평이 아니라 공개 자료에 근거한 독서 길잡이다.", "href": "2026-11-28-book-algorithm-disobedience-ko.html"}, "en": {"title": "What can we recover after we stop scrolling?", "summary": "A new book asks not whether to abandon technology, but whose goals technology serves. Han-na Ju's Algorithm Disobedience places everyday choice at the center. The November 27 News Factory interview and published bibliographic information suggest a question beyond convenience for or against. This is a reading guide based on public material, not a review claiming to have read the entire book.", "href": "2026-11-28-book-algorithm-disobedience-en.html"}, "ja": {"title": "スクロールを止めた後、何を取り戻すのか", "summary": "技術を捨てるかどうかでなく、誰の目標に合わせて動くかを問う本が出た。チュ・ハンナの『アルゴリズム不服従』だ。11月27日のNews Factoryインタビューと公開書誌・目次から見える問いは、便利さへの賛否より日常の選択権に近い。本稿は公開資料による読書ガイドで、全編を読了した書評ではない。", "href": "2026-11-28-book-algorithm-disobedience-ja.html"}, "zh": {"title": "停止滑动屏幕后，我们能拿回什么", "summary": "新书不只是问要不要抛弃技术，而是问技术服务于谁的目标。朱韩娜的《算法不服从》把日常选择权放在中心。结合11月27日News Factory访谈与公开书目，这个问题超越了对便利的简单赞成或反对。本文是基于公开资料的阅读指南，并非声称读完整本书的书评。", "href": "2026-11-28-book-algorithm-disobedience-zh.html"}, "es": {"title": "¿Qué recuperamos cuando dejamos de deslizar la pantalla?", "summary": "Un nuevo libro no pregunta solo si debemos abandonar la tecnología, sino a qué objetivos sirve. La obra de Han-na Ju sobre desobediencia algorítmica pone en el centro la elección cotidiana. La entrevista de News Factory del 27 de noviembre y los datos bibliográficos plantean algo más que estar a favor o en contra de la comodidad. Esta es una guía basada en material público, no una reseña que afirme haber leído el libro completo.", "href": "2026-11-28-book-algorithm-disobedience-es.html"}}, "report-2026-11-28-rider-reissue-not-new-series": {"ko": {"title": "다시 나온 변신벨트, 새 작품과는 다른 뉴스다", "summary": "오래된 변신도 다시 상품이 된다. 반다이는 덴오·빌드·에그제이드 관련 SUPER BEST 상품의 예약을 11월 27일부터 시작한다고 공식 안내했다. 익숙한 작품의 이름과 새로운 상품 소식을 섞으면 후속작 발표처럼 읽히기 쉽다. 이번에 확인된 것은 완구 라인업과 기능 안내다.", "href": "2026-11-28-rider-reissue-not-new-series-ko.html"}, "en": {"title": "A returning transformation belt is not a new television series", "summary": "Old transformations can become products again. Bandai's official notice says reservations for SUPER BEST items associated with Den-O, Build and Ex-Aid open on November 27. Familiar series names and new product announcements can easily be mistaken for sequel news. What has been verified here is a toy lineup and its stated functions.", "href": "2026-11-28-rider-reissue-not-new-series-en.html"}, "ja": {"title": "戻ってきた変身ベルト、新番組とは違うニュースだ", "summary": "昔の変身も再び商品になる。バンダイは電王・ビルド・エグゼイド関連のSUPER BEST商品の予約を11月27日から始めると公式案内した。なじみの作品名と新商品の話を混ぜれば、続編発表のように読めてしまう。今回確認したのは玩具ラインアップと機能案内だ。", "href": "2026-11-28-rider-reissue-not-new-series-ja.html"}, "zh": {"title": "变身腰带再次上架，不等于新剧集发布", "summary": "旧日变身也会再次成为商品。万代官方说明称，电王、Build、Ex-Aid相关SUPER BEST商品从11月27日开始接受预约。熟悉的作品名与新品消息混在一起，很容易被读成续作发布。此次核实的是玩具阵容与功能说明。", "href": "2026-11-28-rider-reissue-not-new-series-zh.html"}, "es": {"title": "Un cinturón de transformación que vuelve no es una serie nueva", "summary": "Las transformaciones antiguas pueden convertirse de nuevo en productos. Bandai anuncia reservas desde el 27 de noviembre para artículos SUPER BEST asociados con Den-O, Build y Ex-Aid. Mezclar nombres conocidos con novedades comerciales puede parecer un anuncio de secuela. Lo verificado aquí es una gama de juguetes y sus funciones anunciadas.", "href": "2026-11-28-rider-reissue-not-new-series-es.html"}}, "report-2026-11-28-three-finance-locks": {"ko": {"title": "안심차단 세 종류, 잠그는 문이 다르다", "summary": "내 명의의 금융거래가 걱정될 때 안심차단을 하나 신청하면 모든 일이 막히는 것일까. 금융위원회는 여신거래·비대면 계좌개설·오픈뱅킹 안심차단을 각각 안내한다. 이름은 비슷해도 막는 거래가 다르다. 편리함을 잠시 줄이는 대신 어떤 위험을 줄이는지 알아야 실제로 쓸 수 있는 보호가 된다.", "href": "2026-11-28-three-finance-locks-ko.html"}, "en": {"title": "Three financial safeguards lock three different doors", "summary": "If you are concerned about transactions in your name, does enabling one safety block stop everything? Korea's Financial Services Commission describes separate safeguards for credit transactions, remote account opening and open banking. Similar names do not mean identical coverage. To use protection effectively, understand which risks are reduced in return for less convenience.", "href": "2026-11-28-three-finance-locks-en.html"}, "ja": {"title": "三つの金融安心遮断、閉める扉が違う", "summary": "自分名義の不正取引が心配なとき、一つの遮断サービスで全部防げるのか。韓国金融委員会は与信取引・非対面口座開設・オープンバンキングを別々に案内する。名前は似ていても止める取引は違う。便利さを少し減らす代わりに、どのリスクを下げるのかを知る必要がある。", "href": "2026-11-28-three-finance-locks-ja.html"}, "zh": {"title": "三种金融安心阻断，锁住不同的门", "summary": "担心有人冒用自己名义交易时，申请一种安心阻断就能拦住所有风险吗？韩国金融委员会分别介绍授信交易、非面对面开户、开放银行三种服务。名称相似，阻断范围并不一样。要知道以少一些便利换来了哪种保护，措施才真正有用。", "href": "2026-11-28-three-finance-locks-zh.html"}, "es": {"title": "Tres protecciones financieras cierran puertas distintas", "summary": "Si teme operaciones a su nombre, ¿activar un solo bloqueo lo detiene todo? La Comisión de Servicios Financieros de Corea describe protecciones separadas para crédito, apertura remota de cuentas y banca abierta. Los nombres similares no implican igual cobertura. Para aprovecharlas, hay que saber qué riesgo se reduce a cambio de menos comodidad.", "href": "2026-11-28-three-finance-locks-es.html"}}, "report-2026-11-28-impeachment-verbs": {"ko": {"title": "발의했다, 의결했다, 파면했다는 다른 문장이다", "summary": "탄핵을 둘러싼 정치적 요구가 커질수록 동사가 중요해진다. 추진단이 글을 쓰는 일과 국회가 소추를 의결하는 일, 헌법재판소가 판단하는 일은 다르다. 11월 27일 뉴스공장 퍼니포에서도 정당의 요구와 일정 조율, 소추안 작성이 함께 논의됐다. 어느 쪽의 정치적 기대도 다음 단계가 이미 끝났다는 증거가 되지는 않는다.", "href": "2026-11-28-impeachment-verbs-ko.html"}, "en": {"title": "Proposed, impeached and removed are different verbs", "summary": "As political demands for impeachment grow louder, verbs matter. Drafting a proposal, a parliamentary vote to impeach and a Constitutional Court decision are separate stages. The November 27 News Factory political discussion covered party demands, scheduling and preparation of a motion. Neither side's political expectations establish that the next stage has already happened.", "href": "2026-11-28-impeachment-verbs-en.html"}, "ja": {"title": "発議、訴追議決、罷免は違う動詞だ", "summary": "弾劾を求める政治的声が強まるほど、動詞が重要になる。案を書くこと、国会が訴追を議決すること、憲法裁判所が判断することは別だ。11月27日のNews Factory政治討論でも、政党の要求と日程調整、案の準備が一緒に扱われた。どちら側の期待も、次の段階が完了した証拠にはならない。", "href": "2026-11-28-impeachment-verbs-ja.html"}, "zh": {"title": "提出、通过弹劾、罢免，是不同的动词", "summary": "弹劾的政治要求越强烈，动词越重要。起草提案、国会通过弹劾、宪法法院裁决，是不同阶段。11月27日News Factory政治讨论同时涉及政党要求、时间协调和弹劾案准备。任何一方的政治期待，都不能证明下一步已经完成。", "href": "2026-11-28-impeachment-verbs-zh.html"}, "es": {"title": "Proponer, aprobar la acusación y destituir son verbos distintos", "summary": "Cuanto más crecen las exigencias políticas de impeachment, más importan los verbos. Redactar una propuesta, una votación parlamentaria de acusación y una decisión del Tribunal Constitucional son etapas separadas. La discusión política de News Factory del 27 de noviembre trató exigencias partidistas, calendario y preparación. Las expectativas de ninguna parte prueban que la siguiente etapa haya terminado.", "href": "2026-11-28-impeachment-verbs-es.html"}}, "report-2026-11-28-ai-world-growth-condition": {"ko": {"title": "AI가 끄는 세계경제, 투자 다음은 수익의 차례다", "summary": "대외경제정책연구원은 11월 17일 내년 세계경제 전망을 발표하며 AI 관련 투자와 교역이 성장을 뒷받침하는 한편 비용 부담이 이어진다고 설명했다. 생산설비와 데이터센터에 돈이 들어가는 것과 그 투자에서 충분한 수익이 나오는 것은 같은 단계가 아니다. 세계경제를 읽는 질문도 투자 규모에서 그 다음으로 옮겨갈 필요가 있다.", "href": "2026-11-28-ai-world-growth-condition-ko.html"}, "en": {"title": "For an AI-led world economy, revenue comes after investment", "summary": "In its November 17 presentation of the world economic outlook for next year, the Korea Institute for International Economic Policy said AI-related investment and trade were supporting growth while cost pressures persisted. Spending on facilities and data centers is not the same stage as earning adequate returns. The economic question needs to move beyond the investment announcement.", "href": "2026-11-28-ai-world-growth-condition-en.html"}, "ja": {"title": "AIが引く世界経済、投資の次は収益の番だ", "summary": "対外経済政策研究院は11月17日の来年の世界経済見通し発表で、AI関連投資と貿易が成長を支える一方、費用負担が続くと説明した。設備やデータセンターに資金が入ることと、十分な利益を得ることは同じ段階ではない。世界経済を見る問いも、投資規模の次へ進む必要がある。", "href": "2026-11-28-ai-world-growth-condition-ja.html"}, "zh": {"title": "AI带动世界经济，投资之后还要看收益", "summary": "韩国对外经济政策研究院11月17日发布明年世界经济展望时指出，AI相关投资和贸易支撑增长，但成本压力持续。钱投入厂房和数据中心，与投资获得足够回报，并不是同一阶段。观察世界经济的问题，也需要从投资规模走向下一步。", "href": "2026-11-28-ai-world-growth-condition-zh.html"}, "es": {"title": "En una economía mundial impulsada por IA, después de invertir toca ingresar", "summary": "En su presentación del 17 de noviembre sobre la economía mundial del próximo año, el Instituto Coreano de Política Económica Internacional señaló que inversión y comercio ligados a IA sostienen el crecimiento, mientras persisten las presiones de costes. Gastar en instalaciones y centros de datos no es la misma fase que obtener rendimientos suficientes. La pregunta económica debe ir más allá del anuncio de inversión.", "href": "2026-11-28-ai-world-growth-condition-es.html"}}, "report-2026-11-28-automated-decision-questions": {"ko": {"title": "기계가 정했다면, 설명은 누구에게 물을까", "summary": "추천 목록과 대출 심사를 모두 알고리즘이라는 한 단어로 부르면 중요한 차이를 놓친다. 11월 27일 뉴스공장 백년위원회는 자동화가 판단과 관계에 미치는 영향을 논의했다. 하지만 기술이 복잡하다는 이유만으로 사회적 책임까지 사라지는 것은 아니다. 모든 자동화가 같은 위험을 갖는 것도 아니다.", "href": "2026-11-28-automated-decision-questions-ko.html"}, "en": {"title": "When a machine decides, whom do we ask to explain?", "summary": "Calling both recommendation lists and lending decisions 'algorithms' hides important differences. News Factory's November 27 interview discussed automation's effects on judgment and relationships. Technical complexity does not make social responsibility disappear. Nor does every kind of automation carry the same risk.", "href": "2026-11-28-automated-decision-questions-en.html"}, "ja": {"title": "機械が決めたなら、誰に説明を求めるのか", "summary": "推薦リストと融資審査をアルゴリズムという一語でくくると、大切な差を見落とす。11月27日のNews Factoryインタビューは自動化が判断や関係に与える影響を論じた。技術が複雑でも社会的責任は消えず、すべての自動化のリスクが同じでもない。", "href": "2026-11-28-automated-decision-questions-ja.html"}, "zh": {"title": "机器作了决定，该向谁要求解释", "summary": "把推荐列表与贷款审核都叫算法，会漏掉重要差异。11月27日News Factory访谈讨论了自动化对判断与关系的影响。技术复杂，并不意味着社会责任会消失。不同自动化也不具有完全相同的风险。", "href": "2026-11-28-automated-decision-questions-zh.html"}, "es": {"title": "Cuando decide una máquina, ¿a quién pedimos explicaciones?", "summary": "Llamar algoritmos tanto a las recomendaciones como a la evaluación de préstamos oculta diferencias importantes. La entrevista de News Factory del 27 de noviembre abordó efectos de la automatización sobre juicio y relaciones. La complejidad técnica no borra la responsabilidad social, ni todas las formas de automatización entrañan el mismo riesgo.", "href": "2026-11-28-automated-decision-questions-es.html"}}};function apply(){const l=document.documentElement.dataset.lang||'ko';for(const a of document.querySelectorAll('#nr-article-grid .nr-card[data-article-id]')){const all=D[a.dataset.articleId];if(!all)continue;const z=all[l]||all.en;a.setAttribute('translate','no');const h=a.querySelector('h3'),p=a.querySelector('p');if(a.dataset.articleId==='report-2026-11-28-morning-briefing'){const b=a.querySelector('b');const label=({ko:'아침 브리핑',en:'Morning briefing',ja:'朝のブリーフィング',zh:'晨间简报',es:'Resumen de la mañana'})[l]||'Morning briefing';if(b&&b.textContent!==label+' · 2026.11.28')b.textContent=label+' · 2026.11.28';}if(h&&h.textContent!==z.title)h.textContent=z.title;if(p&&p.textContent!==z.summary)p.textContent=z.summary;}}new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['data-lang']});const grid=document.getElementById('nr-article-grid');if(grid)new MutationObserver(apply).observe(grid,{childList:true,subtree:true});apply();})();